package com.cvns.controller;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import com.cvns.dtos.ResponseDtos.ApiResponse;import com.cvns.service.ReportService;import lombok.RequiredArgsConstructor;
@RestController @RequestMapping("/reports") @RequiredArgsConstructor public class ReportController{private final ReportService s;@GetMapping("/clinic")@PreAuthorize("hasRole('CLINIC')")public ResponseEntity<?> report(@RequestParam(defaultValue="daily")String period){return ResponseEntity.ok(ApiResponse.success("Clinic report",s.report(period)));}}
